Yes. A small in-memory cache with a time-to-live (TTL) keeps the implementation dependency-free and avoids unnecessary API calls:

```javascript
const weatherCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getWeather(city) {
  const key = city.trim().toLowerCase();
  const cached = weatherCache.get(key);

  if (cached && cached.expiresAt > Date.now()) {
    return cached.data;
  }

  // Remove expired data
  weatherCache.delete(key);

  const url =
    `https://api.openweathermap.org/data/2.5/weather` +
    `?q=${encodeURIComponent(city)}` +
    `&units=metric&appid=YOUR_API_KEY`;

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Weather request failed: ${response.status}`);
  }

  const data = await response.json();

  weatherCache.set(key, {
    data,
    expiresAt: Date.now() + CACHE_TTL
  });

  return data;
}
```

Use it like this:

```javascript
getWeather("London")
  .then(data => console.log(data))
  .catch(error => console.error(error));
```

This cache is fast and adds no dependencies, but it is cleared when the page refreshes. If responses should survive browser restarts, use `localStorage` instead:

```javascript
const CACHE_PREFIX = "weather_cache_";
const CACHE_TTL = 60 * 60 * 1000; // 1 hour

async function getWeather(city) {
  const key = CACHE_PREFIX + city.trim().toLowerCase();
  const stored = localStorage.getItem(key);

  if (stored) {
    try {
      const cached = JSON.parse(stored);

      if (cached.expiresAt > Date.now()) {
        return cached.data;
      }

      localStorage.removeItem(key);
    } catch {
      localStorage.removeItem(key);
    }
  }

  const url =
    `https://api.openweathermap.org/data/2.5/weather` +
    `?q=${encodeURIComponent(city)}` +
    `&units=metric&appid=YOUR_API_KEY`;

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Weather request failed: ${response.status}`);
  }

  const data = await response.json();

  localStorage.setItem(key, JSON.stringify({
    data,
    expiresAt: Date.now() + CACHE_TTL
  }));

  return data;
}
```

For a lightweight app, I’d start with the in-memory version. Use `localStorage` only if persistence across sessions is important, and keep the TTL short enough that weather data remains reasonably fresh.
